import { useState } from "react";
import AdminLayout from "./AdminLayout"; // تأكد من المسار الصحيح

// استيراد المكونات التي تريد عرضها (يجب أن تنشئ هذه الملفات)
// import DashboardOverview from "./DashboardOverview";
// import StudentsList from "./StudentsList";
// import CompaniesList from "./CompaniesList";
// import ValidationsList from "./ValidationsList";

export default function AdminDashboardPage() {
  // 1. تعريف الحالة لمعرفة أي تبويب نشط حالياً
  const [activeTab, setActiveTab] = useState("dashboard");

  // 2. دالة لتغيير التبويب (سيتم تمريرها للـ Sidebar)
  const handleNavigation = (tabId) => {
    setActiveTab(tabId);
  };

  return (
    <AdminLayout 
      active={activeTab} 
      onNav={handleNavigation} 
      pendingCount={9} // يمكنك جلب هذا الرقم من قاعدة البيانات لاحقاً
    >
      {/* 3. عرض المحتوى بناءً على التبويب النشط */}
      <div className="p-6">
        {activeTab === "dashboard" && (
           <div>
             <h2 className="text-2xl font-bold mb-4">Admin Dashboard</h2>
             {/* ضع كود الإحصائيات هنا */}
             <p>Welcome to the overview.</p>
           </div>
        )}

        {activeTab === "validations" && (
           <div>
             <h2 className="text-2xl font-bold mb-4">Pending Validations</h2>
             {/* ضع مكون طلبات التفعيل هنا */}
           </div>
        )}

        {activeTab === "students" && (
           <div>
             <h2 className="text-2xl font-bold mb-4">All Students</h2>
             {/* ضع جدول الطلاب هنا */}
           </div>
        )}

        {activeTab === "companies" && (
           <div>
             <h2 className="text-2xl font-bold mb-4">Registered Companies</h2>
             {/* ضع جدول الشركات هنا */}
           </div>
        )}
      </div>
    </AdminLayout>
  );
}
